69	@RestController
70	@CrossOrigin(exposedHeaders = "errors, content-type")
71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
75	
76	    /**
77	     * Dedicated logger for the welcome notification enqueued when an owner is successfully created.
78	     * The emitted line carries the owner's id and its unified {@link Owner#getMemberId() memberId} so
79	     * downstream notification consumers can address the welcome to the newly registered owner.
80	     */
81	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
82	
83	    /**
84	     * Serializes {@link OwnerCreatedEvent structured audit events} to their JSON form. Stateless and
85	     * thread-safe, so a single shared instance serves every create.
86	     */
87	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
88	
89	    /**
90	     * Monotonically increasing sequence stamped onto each {@link OwnerCreatedEvent OWNER_CREATED}
91	     * event, so the ordering of creates is recoverable from the audit stream alone. Shared across all
92	     * creates (hence {@code static}) and incremented once per emitted event.
93	     */
94	    private static final AtomicLong AUDIT_SEQ = new AtomicLong();
95	
96	    /**
97	     * Immutable structured audit event emitted (as JSON) alongside the human-readable audit line when
98	     * an owner is created. Its {@code memberId} component carries the owner's <em>primary
99	     * identifier</em>, the unified {@link Owner#getMemberId() memberId}, so downstream consumers always
100	     * read the owner's primary identifier from the same event.
101	     *
102	     * <p>The component order matches the serialized field order
103	     * {@code {seq, ownerId, memberId, membershipLevel, event}}.
104	     */
105	    private record OwnerCreatedEvent(long seq, Integer ownerId, String memberId,
106	                                     Integer membershipLevel, String event) {
107	
108	        private static final String OWNER_CREATED = "OWNER_CREATED";
109	
110	        /**
111	         * Assemble the audit event for a just-persisted owner. Every owner-derived component is read
112	         * through a single named accessor ({@link #ownerId(Owner)}, {@link #primaryIdentifier(Owner)},
113	         * {@link #membershipLevel(Owner)}), so the event's schema — the fields it carries and how each
114	         * one is derived from the persisted owner — is defined in one place and extended there.
115	         */
116	        static OwnerCreatedEvent of(long seq, Owner owner) {
117	            return new OwnerCreatedEvent(seq, ownerId(owner), primaryIdentifier(owner),
118	                membershipLevel(owner), OWNER_CREATED);
119	        }
120	
121	        private static Integer ownerId(Owner owner) {
122	            return owner.getId();
123	        }
124	
125	        /**
126	         * The owner's primary identifier: its unified {@link Owner#getMemberId() memberId}.
127	         */
128	        private static String primaryIdentifier(Owner owner) {
129	            return owner.getMemberId();
130	        }
131	
132	        private static Integer membershipLevel(Owner owner) {
133	            return owner.getMembershipLevel();
134	        }
135	    }
136	
137	    /**
138	     * The HTTP request header a client may send to make a create idempotent. When a create repeats
139	     * with a key already seen, the originally created owner is returned instead of a duplicate.
140	     */
141	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
142	
143	    /**
144	     * Remembers, per {@link #IDEMPOTENCY_KEY_HEADER Idempotency-Key}, the id of the owner that key's
145	     * first successful create produced, so a repeat of that create can return the same owner rather
146	     * than creating a duplicate.
147	     */
148	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
149	
150	    /**
151	     * Fixed public-holiday calendar. A registration date that lands on one of these dates is rolled
152	     * forward to the next non-holiday business day, in the same way weekends are.
153	     */
154	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
155	        LocalDate.of(2026, 1, 1),
156	        LocalDate.of(2026, 1, 26),
157	        LocalDate.of(2026, 4, 25),
158	        LocalDate.of(2026, 12, 25),
159	        LocalDate.of(2026, 12, 28));
160	
161	    private final ClinicService clinicService;
162	
163	    private final OwnerMapper ownerMapper;
164	
165	    private final PetMapper petMapper;
166	
167	    private final VisitMapper visitMapper;
168	
169	    private final AddressNormalizer addressNormalizer;
170	
171	    public OwnerRestControllerV1(ClinicService clinicService,
172	                                 OwnerMapper ownerMapper,
173	                                 PetMapper petMapper,
174	                                 VisitMapper visitMapper,
175	                                 AddressNormalizer addressNormalizer) {
176	        this.clinicService = clinicService;
177	        this.ownerMapper = ownerMapper;
178	        this.petMapper = petMapper;
179	        this.visitMapper = visitMapper;
180	        this.addressNormalizer = addressNormalizer;
181	    }
182	
183	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
184	    @Override
185	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
186	        Collection<Owner> owners;
187	        if (lastName != null) {
188	            owners = this.clinicService.findOwnerByLastName(lastName);
189	        } else {
190	            owners = this.clinicService.findAllOwners();
191	        }
192	        if (owners.isEmpty()) {
193	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
194	        }
195	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
196	    }
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Override
200	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
201	        Owner owner = this.clinicService.findOwnerById(ownerId);
202	        if (owner == null) {
203	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
204	        }
205	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
206	    }
207	
208	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
209	    @Override
210	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
211	        String idempotencyKey = currentIdempotencyKey();
212	        if (idempotencyKey != null) {
213	            Integer existingId = idempotentCreates.get(idempotencyKey);
214	            if (existingId != null) {
215	                Owner existing = this.clinicService.findOwnerById(existingId);
216	                if (existing != null) {
217	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
218	                }
219	            }
220	        }
221	
222	        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
223	
224	        if (idempotencyKey != null && response.getStatusCode() == HttpStatus.CREATED
225	            && response.getBody() != null && response.getBody().getId() != null) {
226	            idempotentCreates.put(idempotencyKey, response.getBody().getId());
227	        }
228	        return response;
229	    }
230	
231	    /**
232	     * The non-blank {@link #IDEMPOTENCY_KEY_HEADER Idempotency-Key} header of the request currently
233	     * being handled, or {@code null} when the request carries no such header (or no request is bound
234	     * to the current thread). Used to make a repeated create return the originally created owner.
235	     */
236	    private String currentIdempotencyKey() {
237	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
238	            return null;
239	        }
240	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
241	        return (key == null || key.isBlank()) ? null : key;
242	    }
243	
244	    /**
245	     * Run the full owner-creation pipeline for a submitted {@link OwnerFieldsDto} and build its
246	     * response. The submitted fields are mapped to an {@link Owner}, which is
247	     * {@link #normalizeAndValidate(Owner) normalized and validated}, checked against the
248	     * {@link #isDailyLimitReached(LocalDate) daily creation limit}, {@link #assignHousehold(Owner)
249	     * assigned its household} and screened for {@link #checkForConflicts(Owner) conflicts};
250	     * a surviving owner then has its {@link #assignDerivedAttributes(Owner, boolean) derived
251	     * attributes} assigned, is persisted and audited. Returns the {@link #created(Owner) 201 Created}
252	     * response for the persisted owner, or throws {@link RejectedRequestException} with the status
253	     * the create must fail with ({@code 400 Bad Request}, {@code 429 Too Many Requests} or
254	     * {@code 409 Conflict}) when the owner cannot be created.
255	     */
256	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
257	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
258	
259	        normalizeAndValidate(owner);
260	        if (isDailyLimitReached(owner.getRegistrationDate())) {
261	            throw new RejectedRequestException(HttpStatus.TOO_MANY_REQUESTS);
262	        }
263	
264	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
265	        assignHousehold(owner);
266	
267	        checkForConflicts(owner);
268	
269	        assignDerivedAttributes(owner, sharesHousehold);
270	        this.clinicService.saveOwner(owner);
271	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
272	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
273	            owner.getMembershipLevel());
274	        emitOwnerCreatedEvent(owner);
275	        enqueueWelcomeNotification(owner);
276	        return created(owner);
277	    }
278	
279	    /**
280	     * Enqueue a welcome notification for a just-created owner by emitting a line on the {@code NOTIFY}
281	     * logger that carries the owner's id and its unified {@link Owner#getMemberId() memberId}, so a
282	     * downstream consumer can address the welcome to the newly registered owner.
283	     */
284	    private void enqueueWelcomeNotification(Owner owner) {
285	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
286	    }
287	
288	    /**
289	     * Emit the immutable {@link OwnerCreatedEvent} for a just-persisted owner as a JSON object on the
290	     * {@code AUDIT} logger. A fresh {@link #AUDIT_SEQ monotonic sequence} is stamped onto the event so
291	     * the order of creates is recoverable from the audit stream. The event carries the owner's primary
292	     * identifier, its unified memberId.
293	     */
294	    private void emitOwnerCreatedEvent(Owner owner) {
295	        OwnerCreatedEvent event = OwnerCreatedEvent.of(AUDIT_SEQ.incrementAndGet(), owner);
296	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
297	    }
298	
299	    /**
300	     * Bring a freshly mapped owner into its canonical, valid form, or report the reason it must be
301	     * rejected. The owner's {@link #normalizeAddress(Owner) address is normalized} (a missing address
302	     * is rejected), its telephone is converted to E.164 (an unconvertible number is rejected), its
303	     * postcode is checked against its city's region, a registration date in the future is rejected,
304	     * and the effective registration date (the supplied one, or today when none was given) is rolled
305	     * onto a business day and stored back on the owner. Returns once the owner is valid and
306	     * normalized, or throws {@link RejectedRequestException} with the status the create must fail
307	     * with ({@code 400 Bad Request}) otherwise.
308	     */
309	    private void normalizeAndValidate(Owner owner) {
310	        if (!normalizeAddress(owner)) {
311	            throw new RejectedRequestException(HttpStatus.BAD_REQUEST);
312	        }
313	        String telephone = toE164(owner.getTelephone());
314	        if (telephone == null) {
315	            throw new RejectedRequestException(HttpStatus.BAD_REQUEST);
316	        }
317	        owner.setTelephone(telephone);
318	        if (isDisposableEmail(owner.getEmail())) {
319	            throw new RejectedRequestException(HttpStatus.BAD_REQUEST);
320	        }
321	        if (!owner.isPostcodeValid()) {
322	            throw new RejectedRequestException(HttpStatus.BAD_REQUEST);
323	        }
324	        if (owner.getRegistrationDate() != null
325	            && owner.getRegistrationDate().isAfter(LocalDate.now())) {
326	            throw new RejectedRequestException(HttpStatus.BAD_REQUEST);
327	        }
328	        LocalDate effectiveDate = owner.getRegistrationDate() != null
329	            ? owner.getRegistrationDate() : LocalDate.now();
330	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
331	    }
332	
333	    /**
334	     * Normalize the owner's supplied address into its canonical stored form and report whether an
335	     * address was supplied at all. The owner may supply its address either as the structured
336	     * {@code addressLine1}/{@code addressLine2} fields or as the flat {@code address} field, which is
337	     * kept for backward compatibility; the structured form is preferred whenever a non-blank
338	     * {@code addressLine1} is present. Each supplied field is run through the {@link AddressNormalizer}
339	     * (trimmed, whitespace-collapsed, upper-cased, common street-type abbreviations expanded). When the
340	     * structured form is used, the normalized {@code addressLine1} and {@code addressLine2} are stored
341	     * back and the composed {@link Owner#getAddress() address} becomes the normalized
342	     * {@code addressLine1} with a single space and the normalized {@code addressLine2} appended when an
343	     * {@code addressLine2} is present; when the flat form is used, the normalized flat address is
344	     * stored and no structured lines are kept. Returns {@code true} once a non-blank address has been
345	     * normalized and stored, or {@code false} when neither form supplied an address, in which case the
346	     * create must be rejected with {@code 400 Bad Request}.
347	     */
348	    private boolean normalizeAddress(Owner owner) {
349	        String line1 = addressNormalizer.normalize(owner.getAddressLine1());
350	        if (!line1.isEmpty()) {
351	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
352	            owner.setAddressLine1(line1);
353	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
354	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
355	            return true;
356	        }
357	        String address = addressNormalizer.normalize(owner.getAddress());
358	        if (address.isEmpty()) {
359	            return false;
360	        }
361	        owner.setAddressLine1(null);
362	        owner.setAddressLine2(null);
363	        owner.setAddress(address);
364	        return true;
365	    }
366	
367	    /**
368	     * The set of disposable (throwaway) email domains that an owner's email may not use. An owner
369	     * whose email is hosted on one of these domains is rejected with {@code 400 Bad Request}.
370	     */
371	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
372	        "mailinator.com", "tempmail.com", "guerrillamail.com");
373	
374	    /**
375	     * Whether the given email is hosted on a {@linkplain #DISPOSABLE_EMAIL_DOMAINS disposable}
376	     * domain. The email is optional, so a {@code null} or empty email is not disposable; otherwise
377	     * its {@linkplain Owner#emailDomainOf(String) domain} (compared case-insensitively) is matched
378	     * against the blocklist.
379	     */
380	    private boolean isDisposableEmail(String email) {
381	        String domain = Owner.emailDomainOf(email);
382	        return domain != null && DISPOSABLE_EMAIL_DOMAINS.contains(domain);
383	    }
384	
385	    /**
386	     * Assign the owner its household link. The {@link #householdId(Owner) householdId} is computed
387	     * deterministically from the owner's lastName and postcode, so every owner sharing that
388	     * lastName and postcode is assigned the same value automatically, independent of whether the
389	     * owner declares it shares a household. The link is assigned before the
390	     * {@link #checkForConflicts(Owner) conflict checks} because it feeds the owner's
391	     * {@link #householdSize(String) household size} and {@link #membershipLevel(Owner) membership
392	     * level}.
393	     */
394	    private void assignHousehold(Owner owner) {
395	        owner.setHouseholdId(householdId(owner));
396	    }
397	
398	    /**
399	     * Screen the owner for a clash with an owner that already exists. An owner is rejected with
400	     * {@code 409 Conflict} when it {@linkplain #isDuplicateIdentity(Owner) duplicates an existing
401	     * owner's identity key} or when its {@link #isCityAtCapacity(String) city is already at
402	     * capacity}. Sharing a household (the same surname sound and postcode) but with a different
403	     * identity key is not a conflict: such an owner is admitted and later
404	     * {@linkplain #findSoftDuplicate(Owner) flagged as a possible duplicate}. Returns when the owner
405	     * clashes with nothing and may be created, or throws {@link RejectedRequestException} with
406	     * {@code 409 Conflict} when it clashes.
407	     */
408	    private void checkForConflicts(Owner owner) {
409	        if (isDuplicateIdentity(owner)) {
410	            throw new RejectedRequestException(HttpStatus.CONFLICT);
411	        }
412	        if (isCityAtCapacity(owner.getCity())) {
413	            throw new RejectedRequestException(HttpStatus.CONFLICT);
414	        }
415	    }
416	
417	    /**
418	     * Whether an existing owner already carries this owner's {@link Owner#getIdentityKey() identity
419	     * key}. This is the single hard-duplicate rule: two owners are duplicates exactly when their
420	     * identity keys are equal, and the second is rejected with {@code 409 Conflict}. Like the other
421	     * identity rules it considers only the {@linkplain #activeOwners() active owners}, so an owner
422	     * flagged {@linkplain Owner#isDeleted() deleted} never triggers a duplicate. The email-domain
423	     * blocklist is applied earlier, during {@link #normalizeAndValidate(Owner) validation}, so a
424	     * disposable-email owner is rejected before it reaches this check.
425	     */
426	    private boolean isDuplicateIdentity(Owner owner) {
427	        String identityKey = owner.getIdentityKey();
428	        return activeOwners().stream()
429	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
430	    }
431	
432	    /**
433	     * Build the {@code 201 Created} response for a persisted owner: its {@link OwnerDto} body and a
434	     * {@code Location} header pointing at {@code /api/owners/{id}}.
435	     */
436	    private ResponseEntity<OwnerDto> created(Owner owner) {
437	        HttpHeaders headers = new HttpHeaders();
438	        headers.setLocation(UriComponentsBuilder.newInstance()
439	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
440	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), headers, HttpStatus.CREATED);
441	    }
442	
443	    /**
444	     * Assign the attributes that are derived once, at creation time, and stored on the owner: its
445	     * {@link #memberId(Owner) memberId}, {@link #namesakeCount(String, String) namesakeCount},
446	     * {@link #isBulkSignup(LocalDate) bulk-signup warning}, {@link #isCityApproachingCapacity(String)
447	     * capacity warning}, {@link #householdSize(String)
448	     * householdSize} and {@link #membershipLevel(Owner) membershipLevel}. Each is computed from the
449	     * owner's own fields together with the owners already present, so this runs after the owner has
450	     * been validated and has passed the duplicate and capacity checks, and immediately before it is
451	     * persisted.
452	     */
453	    private void assignDerivedAttributes(Owner owner, boolean sharesHousehold) {
454	        owner.setMemberId(memberId(owner));
455	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
456	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
457	        owner.setCapacityWarning(isCityApproachingCapacity(owner.getCity()));
458	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
459	        owner.setMembershipLevel(membershipLevel(owner));
460	        assignPossibleDuplicate(owner, sharesHousehold);
461	        owner.setRiskFlag(isRiskFlagged(owner));
462	    }
463	
464	    /**
465	     * Whether a newly created owner should be flagged for review. True when any of these hold: the
466	     * owner is a {@linkplain Owner#getPossibleDuplicate() possible duplicate}, its email domain is
467	     * {@linkplain #isDisposableAdjacentEmail(String) disposable-adjacent}, or its city is over its
468	     * soft capacity (the city is {@linkplain #isCityApproachingCapacity(String) approaching capacity},
469	     * so its {@link Owner#getCapacityWarning() capacityWarning} is set); otherwise false. Computed
470	     * during {@link #assignDerivedAttributes(Owner, boolean)}, after the possible-duplicate and
471	     * capacity-warning attributes it reads have already been assigned.
472	     */
473	    private boolean isRiskFlagged(Owner owner) {
474	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
475	            || isDisposableAdjacentEmail(owner.getEmail())
476	            || Boolean.TRUE.equals(owner.getCapacityWarning());
477	    }
478	
479	    /**
480	     * Whether the given email's domain is disposable-adjacent: a subdomain of a known
481	     * {@linkplain #DISPOSABLE_EMAIL_DOMAINS disposable} domain (e.g. {@code x.mailinator.com}). An
482	     * exactly-disposable domain is rejected earlier during {@link #normalizeAndValidate(Owner)
483	     * validation}, so it never reaches here; a subdomain is admitted but still flagged as adjacent.
484	     * The email is optional, so a {@code null} or empty email is not disposable-adjacent; otherwise
485	     * its {@linkplain Owner#emailDomainOf(String) domain} (compared case-insensitively) is tested.
486	     */
487	    private boolean isDisposableAdjacentEmail(String email) {
488	        String domain = Owner.emailDomainOf(email);
489	        if (domain == null) {
490	            return false;
491	        }
492	        return DISPOSABLE_EMAIL_DOMAINS.stream()
493	            .anyMatch(disposable -> domain.endsWith("." + disposable));
494	    }
495	
496	    /**
497	     * The membership level to assign a newly created owner and store on it as its
498	     * {@link Owner#getMembershipLevel() membershipLevel}: the owner's own
499	     * {@linkplain Owner#getBaseMembershipLevel() base level} derived from its membershipPoints,
500	     * capped so it cannot exceed one above the current maximum membershipLevel among the owner's
501	     * existing {@linkplain #householdMembers(String) household members}. With no existing household
502	     * member no cap applies and the base level is used as-is. This is the single place the stored
503	     * membership level is derived; it runs during {@link #assignDerivedAttributes(Owner, boolean)},
504	     * after the owner has passed the duplicate and capacity checks and so has its household members
505	     * available to it.
506	     */
507	    private Integer membershipLevel(Owner owner) {
508	        int base = owner.getBaseMembershipLevel();
509	        Collection<Owner> members = householdMembers(owner.getHouseholdId());
510	        if (members.isEmpty()) {
511	            return base;
512	        }
513	        int householdMax = members.stream()
514	            .mapToInt(Owner::getMembershipLevel)
515	            .max()
516	            .getAsInt();
517	        return Math.min(base, householdMax + 1);
518	    }
519	
520	    /**
521	     * Flag a newly created owner as a possible (soft) duplicate. An owner that declares it shares a
522	     * household ({@code sharesHousehold}) is a declared household member, not a suspected duplicate,
523	     * so it is never flagged. Otherwise it is flagged only when it is a soft match of an existing
524	     * owner as determined by {@link #findSoftDuplicate(Owner)}. When such an owner exists the new owner is flagged with
525	     * {@code possibleDuplicate = true} and {@code possibleDuplicateOf} set to that owner's id;
526	     * otherwise {@code possibleDuplicate = false} and no matching id is recorded.
527	     */
528	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
529	        Owner match = sharesHousehold ? null : findSoftDuplicate(owner);
530	        owner.setPossibleDuplicate(match != null);
531	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
532	    }
533	
534	    /**
535	     * The owners a newly created owner is checked against by the duplicate and identity rules:
536	     * the {@link #householdMembers(String) household} membership and {@link #findSoftDuplicate(Owner)
537	     * soft-duplicate} checks, the {@link #memberId(Owner) memberId} de-duplication and the
538	     * {@link #namesakeCount(String, String) namesake} count. This is the single place that scope is
539	     * defined, so every one of those rules considers exactly the same set of owners; it spans every
540	     * owner the clinic holds except those flagged {@linkplain Owner#isDeleted() deleted}, which a
541	     * soft delete retains but excludes from duplicate and identity detection.
542	     */
543	    private Collection<Owner> activeOwners() {
544	        return this.clinicService.findAllOwners().stream()
545	            .filter(owner -> !owner.isDeleted())
546	            .collect(Collectors.toList());
547	    }
548	
549	    /**
550	     * The existing owner this owner softly duplicates, or {@code null} when there is none. A soft
551	     * match is an existing owner whose {@link Owner#getIdentityKey() identity key} differs from this
552	     * owner's (so it is not already a hard duplicate) but whose lastName has the same
553	     * {@link Owner#soundex(String) soundex} and whose postcode matches; the earliest such owner (by
554	     * id) is returned. Two owners sharing a surname sound and postcode but differing in telephone (or
555	     * email) therefore surface here as a soft match rather than being rejected. A postcode is required
556	     * for a soft match, so an owner without a postcode never matches.
557	     */
558	    private Owner findSoftDuplicate(Owner owner) {
559	        if (owner.getPostcode() == null) {
560	            return null;
561	        }
562	        String candidateSoundex = Owner.soundex(owner.getLastName());
563	        String identityKey = owner.getIdentityKey();
564	        return activeOwners().stream()
565	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
566	            .filter(existing -> Owner.soundex(existing.getLastName()).equals(candidateSoundex))
567	            .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
568	            .min(Comparator.comparingInt(Owner::getId))
569	            .orElse(null);
570	    }
571	
572	    /**
573	     * Build the memberId for a newly created owner, formatted {@code '<REGION><FY><HASH8><CHK>'}: the
574	     * region derived from the owner's postcode (or {@link Owner#UNKNOWN_REGION} when the postcode is
575	     * absent or maps to no known region), the 2-digit fiscal-year code FY of the business-day-adjusted
576	     * registrationDate, the first 8 upper-case hex characters HASH8 of the SHA-256 of the normalized
577	     * (E.164) telephone concatenated with the lastName, and a single Luhn check digit CHK over the
578	     * decimal digits of {@code <REGION><FY><HASH8>} (e.g. {@code 'NSW273C1A9F2B4'}). The
579	     * {@code <REGION><FY><HASH8><CHK>} value is computed by {@link Owner#computeMemberId()}; this is
580	     * the single source of the owner's identity, from which the owner's locality and fiscal year are
581	     * read back.
582	     *
583	     * <p>When the computed memberId collides with an existing owner's {@code memberId}, a
584	     * {@code '-<n>'} suffix is appended with the smallest {@code n} of 2 or more that makes the
585	     * memberId unique, and the de-duplicated memberId is returned.
586	     */
587	    private String memberId(Owner owner) {
588	        String base = owner.computeMemberId();
589	
590	        Set<String> existingIds = activeOwners().stream()
591	            .map(Owner::getMemberId)
592	            .filter(Objects::nonNull)
593	            .collect(Collectors.toSet());
594	
595	        if (!existingIds.contains(base)) {
596	            return base;
597	        }
598	        int n = 2;
599	        while (existingIds.contains(base + "-" + n)) {
600	            n++;
601	        }
602	        return base + "-" + n;
603	    }
604	
605	    /**
606	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
607	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
608	     * (business-day) registration date of the owner being created, so owners are counted per
609	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
610	     */
611	    private boolean isDailyLimitReached(LocalDate day) {
612	        long count = this.clinicService.findAllOwners().stream()
613	            .filter(existing -> day.equals(existing.getRegistrationDate()))
614	            .count();
615	        return count >= 100;
616	    }
617	
618	    /**
619	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
620	     * more than 80 owners have already been created for the given business day. Counts the owners
621	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
622	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
623	     * warning.
624	     */
625	    private boolean isBulkSignup(LocalDate day) {
626	        long count = this.clinicService.findAllOwners().stream()
627	            .filter(existing -> day.equals(existing.getRegistrationDate()))
628	            .count();
629	        return count > 80;
630	    }
631	
632	    /**
633	     * Roll a registration date forward onto a business day: when it falls on a Saturday, Sunday or a
634	     * listed public holiday, advance it to the next non-holiday weekday; an ordinary weekday is
635	     * returned unchanged.
636	     */
637	    private LocalDate toBusinessDay(LocalDate date) {
638	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
639	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
640	            || PUBLIC_HOLIDAYS.contains(date)) {
641	            date = date.plusDays(1);
642	        }
643	        return date;
644	    }
645	
646	    /**
647	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
648	     * more owners. Cities are compared case-insensitively.
649	     */
650	    private boolean isCityAtCapacity(String city) {
651	        return cityOwnerCount(city) >= 50;
652	    }
653	
654	    /**
655	     * Whether the given city is approaching its owner capacity, i.e. it already contains between 40
656	     * and 49 owners (inclusive) and so is nearing the {@link #isCityAtCapacity(String) hard capacity
657	     * limit} of 50. When true, a newly created owner in that city is flagged with a
658	     * {@code capacityWarning}; the hard rejection at 50 is unchanged. Cities are compared
659	     * case-insensitively.
660	     */
661	    private boolean isCityApproachingCapacity(String city) {
662	        long count = cityOwnerCount(city);
663	        return count >= 40 && count <= 49;
664	    }
665	
666	    /**
667	     * The number of existing owners in the given city, compared case-insensitively. Counted over the
668	     * owners present before this create.
669	     */
670	    private long cityOwnerCount(String city) {
671	        return this.clinicService.findAllOwners().stream()
672	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
673	            .count();
674	    }
675	
676	    /**
677	     * The number of existing owners that already share the given firstName and lastName,
678	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
679	     * whitespace runs collapsed). Counted over the owners present before this create.
680	     */
681	    private int namesakeCount(String firstName, String lastName) {
682	        String candidateFirstName = normalizeName(firstName);
683	        String candidateLastName = normalizeName(lastName);
684	        return (int) activeOwners().stream()
685	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
686	                && normalizeName(existing.getLastName()).equals(candidateLastName))
687	            .count();
688	    }
689	
690	    /**
691	     * The number of members in this owner's household after this create: the count of existing
692	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
693	     * created. An owner with no household ({@code householdId == null}) is a household of one.
694	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
695	     * does not depend on the order in which household members were created.
696	     */
697	    private int householdSize(String householdId) {
698	        if (householdId == null) {
699	            return 1;
700	        }
701	        long existing = this.clinicService.findAllOwners().stream()
702	            .filter(other -> householdId.equals(other.getHouseholdId()))
703	            .count();
704	        return (int) existing + 1;
705	    }
706	
707	    /**
708	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
709	     * cannot form a valid E.164 number.
710	     *
711	     * <p>A leading '+' and country code are kept when present; otherwise country code
712	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
713	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
714	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
715	     * exactly the national-digit count that code requires (see
716	     * {@link Owner#hasValidNationalLength}); otherwise it is rejected as invalid.
717	     */
718	    private String toE164(String telephone) {
719	        if (telephone == null) {
720	            return null;
721	        }
722	        boolean hasCountryCode = telephone.trim().startsWith("+");
723	        String digits = telephone.replaceAll("\\D", "");
724	        String e164;
725	        if (hasCountryCode) {
726	            e164 = digits;
727	        } else {
728	            if (digits.startsWith("0")) {
729	                digits = digits.substring(1);
730	            }
731	            e164 = "61" + digits;
732	        }
733	        if (e164.length() < 8 || e164.length() > 15) {
734	            return null;
735	        }
736	        if (!Owner.hasValidNationalLength(e164)) {
737	            return null;
738	        }
739	        return "+" + e164;
740	    }
741	
742	    /**
743	     * The existing owners already registered in the household identified by {@code householdId}: the
744	     * {@linkplain #activeOwners() active owners} carrying that same non-null householdId. The owner
745	     * being created is not yet persisted, so it is never among them, and a {@code null} householdId
746	     * (an owner with no household) yields an empty collection. This is the single source of a
747	     * household's existing membership, shared by every rule keyed by an owner's household (the
748	     * {@link #membershipLevel(Owner) membership-level} derivation) so the set is never re-derived
749	     * elsewhere; like the other identity rules it ignores {@linkplain Owner#isDeleted() deleted}
750	     * owners.
751	     */
752	    private Collection<Owner> householdMembers(String householdId) {
753	        if (householdId == null) {
754	            return List.of();
755	        }
756	        return activeOwners().stream()
757	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
758	            .collect(Collectors.toList());
759	    }
760	
761	    /**
762	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
763	     * to a single space and lower-case. A null value normalizes to the empty string.
764	     */
765	    private String normalizeName(String value) {
766	        if (value == null) {
767	            return "";
768	        }
769	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
770	    }
771	
772	    /**
773	     * A stable shared identifier for the household an owner belongs to, derived deterministically
774	     * from its lastName and postcode. The lastName is normalized (case-insensitive,
775	     * whitespace-collapsed) before hashing, so every owner sharing the same lastName and postcode is
776	     * assigned the same value regardless of the order in which they are created. Formatted as the
777	     * first 12 upper-case hex characters of the SHA-256 of {@code '<normalizedLastName>|<postcode>'}
778	     * (an absent postcode contributes the empty string).
779	     */
780	    private String householdId(Owner owner) {
781	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
782	        String key = normalizeName(owner.getLastName()) + "|" + postcode;
783	        return shaHexUpper(key).substring(0, 12);
784	    }
785	
786	    /**
787	     * The upper-case rendering of the {@linkplain HashUtils#sha256Hex(String) SHA-256 hex} of
788	     * {@code input} (two hex characters per digest byte, so 64 characters in all). Callers that
789	     * need a shorter opaque token take a prefix of the result (e.g. {@link #householdId} keeps the
790	     * first 12 characters). The hashing itself lives in {@link HashUtils} so the one implementation is
791	     * shared with the owner's {@link Owner#getIdentityKey() identity key} and its
792	     * {@link Owner#computeMemberId() memberId} HASH8.
793	     */
794	    private String shaHexUpper(String input) {
795	        return HashUtils.sha256Hex(input).toUpperCase();
796	    }
797	
798	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
799	    @Override
800	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
801	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
802	        if (currentOwner == null) {
803	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
804	        }
805	        currentOwner.setAddress(ownerFieldsDto.getAddress());
806	        currentOwner.setCity(ownerFieldsDto.getCity());
807	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
808	        currentOwner.setLastName(ownerFieldsDto.getLastName());
809	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
810	        this.clinicService.saveOwner(currentOwner);
811	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
812	    }
813	
814	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
815	    @Transactional
816	    @Override
817	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
818	        Owner owner = this.clinicService.findOwnerById(ownerId);
819	        if (owner == null) {
820	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
821	        }
822	        this.clinicService.deleteOwner(owner);
823	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
824	    }
825	
826	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
827	    @Override
828	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
829	        Owner owner = this.clinicService.findOwnerById(ownerId);
830	        if (owner == null) {
831	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
832	        }
833	        HttpHeaders headers = new HttpHeaders();
834	        Pet pet = petMapper.toPet(petFieldsDto);
835	        owner.setId(ownerId);
836	        pet.setOwner(owner);
837	        pet.getType().setName(null);
838	        this.clinicService.savePet(pet);
839	        PetDto petDto = petMapper.toPetDto(pet);
840	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
841	            .buildAndExpand(pet.getId()).toUri());
842	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
843	    }
844	
845	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
846	    @Override
847	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
848	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
849	        if (currentOwner != null) {
850	            Pet currentPet = this.clinicService.findPetById(petId);
851	            if (currentPet != null) {
852	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
853	                currentPet.setName(petFieldsDto.getName());
854	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
855	                this.clinicService.savePet(currentPet);
856	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
857	            }
858	        }
859	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
860	    }
861	
862	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
863	    @Override
864	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
865	        HttpHeaders headers = new HttpHeaders();
866	        Visit visit = visitMapper.toVisit(visitFieldsDto);
867	        Pet pet = new Pet();
868	        pet.setId(petId);
869	        visit.setPet(pet);
870	        this.clinicService.saveVisit(visit);
871	        VisitDto visitDto = visitMapper.toVisitDto(visit);
872	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
873	            .buildAndExpand(visit.getId()).toUri());
874	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
875	    }
876	
877	
878	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
879	    @Override
880	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
881	        Owner owner = this.clinicService.findOwnerById(ownerId);
882	        if (owner != null) {
883	            Pet pet = owner.getPet(petId);
884	            if (pet != null) {
885	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
886	            }
887	        }
888	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
889	    }
890	}
