297	    /**
298	     * Whether the owner has been soft-deleted. A newly created owner is {@code false};
299	     * {@code DELETE /api/owners/{id}} marks the owner {@code deleted} while retaining the row, and
300	     * a deleted owner is ignored by the create endpoint's duplicate and identity checks.
301	     */
302	    public boolean isDeleted() {
303	        return this.deleted;
304	    }
305	
306	    public void setDeleted(boolean deleted) {
307	        this.deleted = deleted;
308	    }
309	
310	    /**
311	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
312	     */
313	    public String getDisplayName() {
314	        return this.getLastName() + ", " + this.getFirstName();
315	    }
316	
317	    /**
318	     * The canonical URL path of this owner: {@code '/api/owners/'} followed by the owner's
319	     * {@linkplain #getId() id}, e.g. {@code '/api/owners/1'}.
320	     */
321	    public String getSelfLink() {
322	        return "/api/owners/" + this.getId();
323	    }
324	
325	    /**
326	     * The owner's initials: the upper-cased first letters of firstName and lastName,
327	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
328	     */
329	    public String getInitials() {
330	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
331	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
332	    }
333	
334	    /**
335	     * The fixed length of the tail that every {@linkplain #getMemberId() memberId} carries after its
336	     * {@code <REGION>} prefix: the 2-digit fiscal-year code, the 8-character HASH8 and the single Luhn
337	     * check digit ({@code 2 + 8 + 1 = 11}). The region prefix is therefore everything in the memberId
338	     * (before any collision suffix) up to this trailing block, so the region and fiscal-year segments
339	     * are read back from the memberId rather than re-derived.
340	     */
341	    private static final int MEMBER_ID_TAIL = 11;
342	
343	    /**
344	     * The owner's base memberId, formatted {@code '<REGION><FY><HASH8><CHK>'}: the
345	     * {@linkplain #getRegion() region} derived from the owner's postcode (or {@link #UNKNOWN_REGION}
346	     * when the postcode maps to no known region), the 2-digit {@linkplain #fiscalYearCode() fiscal-year
347	     * code} FY, the 8 upper-case hex HASH8 (the first 8 hex characters of the SHA-256 of the normalized
348	     * (E.164) telephone concatenated with the lastName, the same HASH8 the region-and-hash identity
349	     * uses), and a single Luhn {@linkplain #luhnCheckDigit(String) check digit} CHK computed over the
350	     * decimal digits of {@code <REGION><FY><HASH8>}, e.g. {@code 'NSW273C1A9F2B4'}. This is the single
351	     * source of the owner's identity; the stored {@linkplain #getMemberId() memberId} is this value
352	     * (with a collision suffix appended only when it clashes with an existing owner's), and the owner's
353	     * {@linkplain #getFiscalYear() fiscal year} is read back from it. Its {@code <REGION>} component is
354	     * the {@linkplain #regionCode() region code} the identifiers are built from.
355	     */
356	    public String computeMemberId() {
357	        String hash8 = HashUtils.sha256Hex(this.telephone + this.getLastName()).toUpperCase().substring(0, 8);
358	        String prefix = regionCode() + fiscalYearCode() + hash8;
359	        return prefix + luhnCheckDigit(prefix);
360	    }
361	
362	    /**
363	     * The {@linkplain #getMemberId() memberId} without its collision suffix: the memberId up to the
364	     * first {@code '-'} (the {@code '-<n>'} suffix appended only to de-duplicate a clashing id), or
365	     * {@code null} when the owner has no memberId. This is the {@code '<REGION><FY><HASH8><CHK>'} base
366	     * from which the {@linkplain #getFiscalYear() fiscal year} is read.
367	     */
368	    private String memberIdBase() {
369	        if (this.memberId == null) {
370	            return null;
371	        }
372	        int dash = this.memberId.indexOf('-');
373	        return dash < 0 ? this.memberId : this.memberId.substring(0, dash);
374	    }
375	
376	    /**
377	     * The owner's fiscal year, formatted {@code 'FY<YY>'}, e.g. {@code 'FY27'}. The two YY digits are
378	     * read from the {@linkplain #getMemberId() memberId} (the {@code <FY>} segment embedded in it), so
379	     * the fiscal-year value shares the owner's single memberId identity; for an owner that has no
380	     * memberId the digits fall back to the {@linkplain #fiscalYearCode() fiscal-year code} of the
381	     * (business-day-adjusted) {@link #registrationDate}. The fiscal year starts on 1 July and is
382	     * labelled by the calendar year in which it ends.
383	     */
384	    public String getFiscalYear() {
385	        String base = memberIdBase();
386	        if (base != null && base.length() >= MEMBER_ID_TAIL) {
387	            return "FY" + base.substring(base.length() - MEMBER_ID_TAIL, base.length() - MEMBER_ID_TAIL + 2);
388	        }
389	        return "FY" + fiscalYearCode();
390	    }
391	
392	    /**
393	     * The two-digit fiscal-year code {@code '<YY>'}: the last two digits of the
394	     * {@linkplain #fiscalYearOf(LocalDate) fiscal year} of the (business-day-adjusted)
395	     * {@link #registrationDate}, zero-padded, e.g. {@code '27'}. This is the FY segment embedded in the
396	     * owner's {@linkplain #computeMemberId() memberId} at creation, and the fallback the
397	     * {@linkplain #getFiscalYear() fiscal year} reads when no memberId is present.
398	     */
399	    private String fiscalYearCode() {
400	        return String.format("%02d", fiscalYearOf(this.registrationDate) % 100);
401	    }
402	
403	    /**
404	     * The fiscal year that contains the given date, identified by the calendar year in which it
405	     * ends. The fiscal year starts on 1 July, so a date in July through December belongs to the
406	     * fiscal year ending in the following calendar year, while a date in January through June
407	     * belongs to the fiscal year ending in the same calendar year.
408	     */
409	    private static int fiscalYearOf(LocalDate date) {
410	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
411	    }
412	
413	    /**
414	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) over the decimal digits
415	     * contained in {@code value}. Reading the digits right to left, every second one is
416	     * doubled (subtracting 9 whenever doubling yields a value above 9); the transformed
417	     * digits are summed, and the check digit is the amount that must be added to that sum to
418	     * reach the next multiple of ten. Any non-digit character in {@code value} is ignored, so
419	     * the digit is taken over exactly the digits the string carries.
420	     */
421	    private static int luhnCheckDigit(String value) {
422	        int sum = 0;
423	        boolean doubling = true;
424	        for (int i = value.length() - 1; i >= 0; i--) {
425	            char c = value.charAt(i);
426	            if (c < '0' || c > '9') {
427	                continue;
428	            }
429	            int digit = c - '0';
430	            if (doubling) {
431	                digit *= 2;
432	                if (digit > 9) {
433	                    digit -= 9;
434	                }
435	            }
436	            sum += digit;
437	            doubling = !doubling;
438	        }
439	        return (10 - (sum % 10)) % 10;
440	    }
441	
442	    /** Fixed city-to-region table used to derive an owner's locality. */
443	    private static final Map<String, String> CITY_REGION = Map.of(
444	        "Sydney", "NSW",
445	        "Melbourne", "VIC",
446	        "Brisbane", "QLD");
447	
448	    /** The region reported for a city that is not present in {@link #CITY_REGION}. */
449	    public static final String UNKNOWN_REGION = "UNKNOWN";
450	
451	    /**
452	     * The canonical region for a city, derived from the fixed city-to-region table
453	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), or
454	     * {@link #UNKNOWN_REGION} when the city is not in the table. This is the single
455	     * source of the city-to-region mapping, shared by every rule that is keyed by
456	     * region so the mapping is never re-derived elsewhere.
457	     */
458	    public static String regionOf(String city) {
459	        return CITY_REGION.getOrDefault(city, UNKNOWN_REGION);
460	    }
461	
462	    /**
463	     * The postcode-derived region of this owner, defaulting to {@link #UNKNOWN_REGION} when the
464	     * postcode maps to no known region: the {@linkplain #getRegion() region} for the owner's postcode,
465	     * or {@link #UNKNOWN_REGION} when there is none. This is the single source of the "region, or
466	     * UNKNOWN when unknown" value, shared by the user-facing {@linkplain #getLocality() locality} and
467	     * the {@linkplain #regionCode() region code embedded in the identifiers} so the two are derived
468	     * from one place.
469	     */
470	    private String regionOrUnknown() {
471	        return getRegion() != null ? getRegion() : UNKNOWN_REGION;
472	    }
473	
474	    /**
475	     * The region code embedded in the owner's identifiers: currently the plain
476	     * {@linkplain #regionOrUnknown() postcode-derived region}, the {@code <REGION>} component built
477	     * into the owner's {@linkplain #computeMemberId() memberId}. It is kept as its own derivation,
478	     * separate from the user-facing {@linkplain #getLocality() locality} (which reports the same region
479	     * today), so the region code carried inside the identifiers can be derived independently of the
480	     * region shown to clients.
481	     */
482	    private String regionCode() {
483	        return regionOrUnknown();
484	    }
485	
486	    /**
487	     * The owner's locality: the plain {@code <REGION>} the owner belongs to, i.e. the
488	     * {@linkplain #getRegion() region} derived from the owner's postcode, or {@link #UNKNOWN_REGION}
489	     * when the postcode maps to no known region. This is the region as shown to clients; it matches the
490	     * {@code <REGION>} component the {@linkplain #computeMemberId() memberId} is built from today, but
491	     * is derived directly from the owner's region rather than read back from the memberId, so the
492	     * {@linkplain #regionCode() region code carried inside the identifiers} can vary without changing
493	     * the locality. The owner's {@linkplain #getTimezone() timezone} and
494	     * {@linkplain #getOwnerSegment() segment} read this locality.
495	     */
496	    public String getLocality() {
497	        return regionOrUnknown();
498	    }
499	
500	    /** Fixed region-to-timezone table, mapping a region to its IANA timezone name. */
501	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
502	        "NSW", "Australia/Sydney",
503	        "VIC", "Australia/Melbourne",
504	        "QLD", "Australia/Brisbane");
505	
506	    /**
507	     * The owner's timezone: the IANA name for this owner's {@linkplain #getLocality() locality},
508	     * looked up in the fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
509	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or {@code null} when
510	     * the locality maps to no known region (e.g. {@link #UNKNOWN_REGION}). It reads the locality
511	     * rather than re-deriving a region so the timezone shares the owner's single region identity.
512	     */
513	    public String getTimezone() {
514	        return REGION_TIMEZONE.get(getLocality());
515	    }
516	
517	    /**
518	     * The owner's segment, formatted {@code '<TIER>_<AREA>'}, one of {@code 'PREMIUM_METRO'},
519	     * {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or {@code 'STANDARD_REGIONAL'}. TIER is
520	     * {@code 'PREMIUM'} when {@linkplain #getMembershipLevel() membershipLevel} is 3 or more,
521	     * otherwise {@code 'STANDARD'}. AREA is {@code 'METRO'} when the owner's
522	     * {@linkplain #getLocality() locality} is a known region (NSW, VIC or QLD), otherwise
523	     * {@code 'REGIONAL'}. It reads the locality against the shared region table so it never
524	     * re-derives a region of its own.
525	     */
526	    public String getOwnerSegment() {
527	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
528	        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
529	        return tier + "_" + area;
530	    }
531	
532	    /**
533	     * The region derived from this owner's postcode alone: the region whose fixed
534	     * {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the postcode, or {@code null}
535	     * when the postcode is absent, not four digits, or in no known range. Defaulted to
536	     * {@link #UNKNOWN_REGION} by {@link #regionOrUnknown()}, it is the source of both the owner's
537	     * user-facing {@linkplain #getLocality() locality} and the {@linkplain #regionCode() region code}
538	     * built into the owner's {@linkplain #computeMemberId() memberId}. It is the single place a region
539	     * is read from an owner's postcode, so every rule keyed by the postcode-derived region shares one
540	     * derivation.
541	     */
542	    public String getRegion() {
543	        return regionOfPostcode(this.postcode);
544	    }
545	
546	    /**
547	     * The region whose fixed {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the
548	     * given postcode, or {@code null} when the postcode is {@code null}, not four digits, or in
549	     * no known range.
550	     */
551	    private static String regionOfPostcode(String postcode) {
552	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
553	            return null;
554	        }
555	        int value = Integer.parseInt(postcode);
556	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
557	            int[] range = entry.getValue();
558	            if (value >= range[0] && value <= range[1]) {
559	                return entry.getKey();
560	            }
561	        }
562	        return null;
563	    }
564	
565	    /**
566	     * Fixed inclusive 4-digit postcode ranges keyed by region, as {@code {low, high}}:
567	     * {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}. A region not
568	     * listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode.
569	     */
570	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
571	        "NSW", new int[] {2000, 2099},
572	        "VIC", new int[] {3000, 3099},
573	        "QLD", new int[] {4000, 4099});
574	
575	    /**
576	     * Whether this owner's postcode is acceptable for its city. Postcode is optional, so a
577	     * {@code null} postcode is accepted. When present it must be four digits and, for a city
578	     * whose {@linkplain #regionOf(String) region} is known, fall within that region's fixed
579	     * inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); a
580	     * city with no known region accepts any 4-digit postcode.
581	     */
582	    public boolean isPostcodeValid() {
583	        if (this.postcode == null) {
584	            return true;
585	        }
586	        if (!this.postcode.matches("[0-9]{4}")) {
587	            return false;
588	        }
589	        int[] range = REGION_POSTCODE_RANGE.get(regionOf(this.city));
590	        if (range == null) {
591	            return true;
592	        }
593	        int value = Integer.parseInt(this.postcode);
594	        return value >= range[0] && value <= range[1];
595	    }
596	
597	    /**
598	     * The national (subscriber) digit count required by each known country calling code, keyed by
599	     * the code's digits (without the leading {@code '+'}): {@code '+1'} carries 10 national digits
600	     * and {@code '+61'} carries 9. This is the single source of the country-calling-code table,
601	     * shared by every rule keyed by an E.164 number's country code so the mapping is never
602	     * re-derived elsewhere.
603	     */
604	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
605	        "1", 10,
606	        "61", 9);
607	
608	    /**
609	     * The country calling code (its digits, without the leading {@code '+'}) that prefixes the given
610	     * E.164 digit string, choosing the longest matching code known to
611	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}, or {@code null} when the number begins with no known
612	     * country code. This is the single place a country code is read from an E.164 number, so every
613	     * rule keyed by that code shares one derivation.
614	     */
615	    private static String countryCodeOf(String e164Digits) {
616	        return NATIONAL_DIGITS_BY_COUNTRY.keySet().stream()
617	            .filter(e164Digits::startsWith)
618	            .max(Comparator.comparingInt(String::length))
619	            .orElse(null);
620	    }
621	
622	    /**
623	     * Whether the E.164 digit string (no leading {@code '+'}) carries the national-number length
624	     * required by its {@linkplain #countryCodeOf(String) country calling code}. The longest matching
625	     * known code wins; a number whose country code is not recognised passes this check (its length is
626	     * then governed only by the general E.164 bound), while a recognised code must be followed by
627	     * exactly the national-digit count it requires ({@code '+1'} 10, {@code '+61'} 9).
628	     */
629	    public static boolean hasValidNationalLength(String e164Digits) {
630	        String countryCode = countryCodeOf(e164Digits);
631	        if (countryCode == null) {
632	            return true;
633	        }
634	        return e164Digits.length() - countryCode.length() == NATIONAL_DIGITS_BY_COUNTRY.get(countryCode);
635	    }
636	
637	    /**
638	     * The owner's membership points: they start at 0, gain 2 when an email is present, gain 1 when
639	     * namesakeCount is 0, gain 2 for a {@linkplain #hasLargeHousehold() household of 3 or more}, and
640	     * gain 3 when the owner's {@linkplain #getTenureFiscalYears() tenure} spans at least one
641	     * elapsed fiscal year. The email, namesake and household factors are available on creation; the
642	     * tenure factor is reached only once at least one fiscal-year boundary has passed.
643	     */
644	    public Integer getMembershipPoints() {
645	        int points = 0;
646	        if (hasEmail()) {
647	            points += 2;
648	        }
649	        if (hasNoNamesakes()) {
650	            points += 1;
651	        }
652	        if (hasLargeHousehold()) {
653	            points += 2;
654	        }
655	        if (hasQualifyingTenure()) {
656	            points += 3;
657	        }
658	        return points;
659	    }
660	
661	    /**
662	     * The owner's membership level, a number from 1 to 4. For an owner created through the
663	     * creation pipeline this is the value assigned and stored at creation time; an owner that
664	     * carries no assigned level (e.g. seed data, or an owner not created through that pipeline)
665	     * reports its {@linkplain #getBaseMembershipLevel() base level} derived from its
666	     * membershipPoints. This is the single value read by the API for an owner's membership level.
667	     */
668	    public Integer getMembershipLevel() {
669	        return this.membershipLevel != null ? this.membershipLevel : getBaseMembershipLevel();
670	    }
671	
672	    public void setMembershipLevel(Integer membershipLevel) {
673	        this.membershipLevel = membershipLevel;
674	    }
675	
676	    /**
677	     * The owner's base membership level, a number from 1 to 4 derived directly from
678	     * {@linkplain #getMembershipPoints() membershipPoints}: level 1 for 0-1 points, level 2 for 2-3,
679	     * level 3 for 4-5, and level 4 for 6 or more. This is the level the creation pipeline starts
680	     * from when it assigns the owner's stored {@linkplain #getMembershipLevel() membershipLevel}.
681	     */
682	    public Integer getBaseMembershipLevel() {
683	        int points = getMembershipPoints();
684	        if (points >= 6) {
685	            return 4;
686	        }
687	        if (points >= 4) {
688	            return 3;
689	        }
690	        if (points >= 2) {
691	            return 2;
692	        }
693	        return 1;
694	    }
695	
696	    /**
697	     * Whether this owner belongs to a household of three or more: its {@link #getHouseholdSize()
698	     * householdSize} is {@code 3} or greater. A {@code null} householdSize, meaning the size is not
699	     * known, is treated as not a large household.
700	     */
701	    private boolean hasLargeHousehold() {
702	        return this.householdSize != null && this.householdSize >= 3;
703	    }
704	
705	    /**
706	     * Whether this owner has an email on record: a non-{@code null}, non-empty {@link #getEmail()
707	     * email}. This is the single source of the "has an email" test, shared by every rule keyed by
708	     * email presence so the check is never re-derived elsewhere.
709	     */
710	    private boolean hasEmail() {
711	        return this.email != null && !this.email.isEmpty();
712	    }
713	
714	    /**
715	     * The domain of an email address: the part after the last {@code '@'}, lower-cased, or
716	     * {@code null} when the email is {@code null} or carries no {@code '@'} (an empty local part or
717	     * empty domain is kept as-is). This is the single place an email's domain is read, shared by
718	     * every rule keyed by the email domain so the domain is never re-parsed elsewhere.
719	     */
720	    public static String emailDomainOf(String email) {
721	        if (email == null) {
722	            return null;
723	        }
724	        int at = email.lastIndexOf('@');
725	        if (at < 0) {
726	            return null;
727	        }
728	        return email.substring(at + 1).toLowerCase();
729	    }
730	
731	    /**
732	     * Whether this owner's name is unique in the clinic: its {@link #getNamesakeCount() namesakeCount}
733	     * is {@code 0} (no other owner shares the name). A {@code null} namesakeCount, meaning the count is
734	     * not known, is treated as not unique.
735	     */
736	    private boolean hasNoNamesakes() {
737	        return this.namesakeCount != null && this.namesakeCount == 0;
738	    }
739	
740	    /**
741	     * Whether this owner's {@linkplain #getTenureFiscalYears() tenure} spans at least one elapsed
742	     * fiscal year. A newly created owner (zero elapsed fiscal years) does not qualify; the threshold
743	     * is crossed only once at least one fiscal-year boundary has passed since registration.
744	     */
745	    private boolean hasQualifyingTenure() {
746	        return this.getTenureFiscalYears() >= 1;
747	    }
748	
749	    /**
750	     * The owner's tenure in elapsed fiscal years: the number of fiscal-year boundaries between the
751	     * {@linkplain #fiscalYearOf(LocalDate) fiscal year} of the {@link #registrationDate} and the
752	     * fiscal year of the current date, or {@code 0} when the registrationDate is not yet set (a newly
753	     * created owner has zero tenure). Never negative.
754	     */
755	    public long getTenureFiscalYears() {
756	        if (this.registrationDate == null) {
757	            return 0;
758	        }
759	        return Math.max(0, fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate));
760	    }
761	
762	    /**
763	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
764	     * otherwise {@code 'PHONE'}.
765	     */
766	    public String getContactPreference() {
767	        return hasEmail() ? "EMAIL" : "PHONE";
768	    }
769	
770	    /**
771	     * The owner's stored E.164 {@linkplain #getTelephone() telephone} formatted for humans:
772	     * a {@code '+'}, the {@linkplain #countryCodeOf(String) country calling code}, a space, and
773	     * the national digits grouped into threes from the left separated by spaces,
774	     * e.g. {@code '+61412345678'} -> {@code '+61 412 345 678'}. The raw {@link #getTelephone()
775	     * telephone} stays in E.164. Returns the telephone unchanged when it is {@code null}, not in
776	     * E.164 form, or carries no known country code.
777	     */
778	    public String getTelephoneDisplay() {
779	        if (this.telephone == null || !this.telephone.startsWith("+")) {
780	            return this.telephone;
781	        }
782	        String digits = this.telephone.substring(1);
783	        String countryCode = countryCodeOf(digits);
784	        if (countryCode == null) {
785	            return this.telephone;
786	        }
787	        String national = digits.substring(countryCode.length());
788	        StringBuilder groups = new StringBuilder();
789	        for (int i = 0; i < national.length(); i += 3) {
790	            if (groups.length() > 0) {
791	                groups.append(' ');
792	            }
793	            groups.append(national, i, Math.min(i + 3, national.length()));
794	        }
795	        return "+" + countryCode + " " + groups;
796	    }
797	
798	    /**
799	     * The owner's identity key: the single derived value used for duplicate detection. It is the
800	     * lower-case hex SHA-256 (64 characters) of the normalized (E.164) telephone, the email
801	     * (already lower-cased, or the empty string when absent) and the {@linkplain #soundex(String)
802	     * soundex} of the lastName, joined with {@code '|'} before hashing, e.g. the digest of
803	     * {@code '+61412345678|jane@example.test|J500'}. Two owners are duplicates, and the second is
804	     * rejected with {@code 409}, only when their whole identity keys are equal.
805	     */
806	    public String getIdentityKey() {
807	        return HashUtils.sha256Hex(identityKeyMaterial());
808	    }
809	
810	    /**
811	     * The material hashed into the owner's {@linkplain #getIdentityKey() identity key}: the normalized
812	     * (E.164) telephone, the email (already lower-cased, or the empty string when absent) and the
813	     * {@linkplain #soundex(String) soundex} of the lastName, joined with {@code '|'} (e.g.
814	     * {@code '+61412345678|jane@example.test|J500'}). Isolating the material keeps the exact set of
815	     * fields the identity key is derived from in a single place.
816	     */
817	    private String identityKeyMaterial() {
818	        String telephonePart = this.telephone == null ? "" : this.telephone;
819	        String emailPart = this.email == null ? "" : this.email;
820	        String soundexPart = soundex(this.getLastName());
821	        return telephonePart + "|" + emailPart + "|" + soundexPart;
822	    }
823	
824	    /**
825	     * The American Soundex code of {@code name}: its first letter followed by three digits encoding
826	     * the remaining consonant sounds ({@code b,f,p,v -> 1}; {@code c,g,j,k,q,s,x,z -> 2};
827	     * {@code d,t -> 3}; {@code l -> 4}; {@code m,n -> 5}; {@code r -> 6}; vowels and {@code h,w,y}
828	     * are not coded). Adjacent letters with the same code, and same-coded letters separated only by
829	     * {@code h} or {@code w}, contribute a single digit; a vowel between two same-coded letters
830	     * keeps both. The result is right-padded with zeros and truncated to four characters. Non-letters
831	     * are ignored, and a {@code null} or letter-free name yields the empty string. Used to build the
832	     * owner's {@link #getIdentityKey() identity key} and to group households by surname sound.
833	     */
834	    public static String soundex(String name) {
835	        if (name == null) {
836	            return "";
837	        }
838	        String letters = name.toUpperCase().replaceAll("[^A-Z]", "");
839	        if (letters.isEmpty()) {
840	            return "";
841	        }
842	        StringBuilder code = new StringBuilder();
843	        code.append(letters.charAt(0));
844	        char previous = soundexDigit(letters.charAt(0));
845	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
846	            char c = letters.charAt(i);
847	            char digit = soundexDigit(c);
848	            if (digit != '0' && digit != previous) {
849	                code.append(digit);
850	            }
851	            if (c != 'H' && c != 'W') {
852	                previous = digit;
853	            }
854	        }
855	        while (code.length() < 4) {
856	            code.append('0');
857	        }
858	        return code.toString();
859	    }
860	
861	    /**
862	     * The Soundex digit for a single upper-case letter (see {@link #soundex(String)}), or
863	     * {@code '0'} for a letter that is not coded (a vowel, or {@code h}, {@code w} or {@code y}).
864	     */
865	    private static char soundexDigit(char c) {
866	        switch (c) {
867	            case 'B': case 'F': case 'P': case 'V':
868	                return '1';
869	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
870	                return '2';
871	            case 'D': case 'T':
872	                return '3';
873	            case 'L':
874	                return '4';
875	            case 'M': case 'N':
876	                return '5';
877	            case 'R':
878	                return '6';
879	            default:
880	                return '0';
881	        }
882	    }
883	
884	    protected Set<Pet> getPetsInternal() {
885	        if (this.pets == null) {
886	            this.pets = new HashSet<>();
887	        }
888	        return this.pets;
889	    }
890	
891	    protected void setPetsInternal(Set<Pet> pets) {
892	        this.pets = pets;
893	    }
894	
895	    public List<Pet> getPets() {
896	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
897	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
898	        return Collections.unmodifiableList(sortedPets);
899	    }
900	
901	    public void setPets(List<Pet> pets) {
902	        this.pets = new HashSet<>(pets);
903	    }
904	
905	    public void addPet(Pet pet) {
906	        getPetsInternal().add(pet);
907	        pet.setOwner(this);
908	    }
909	
910	    /**
911	     * Return the Pet with the given name, or null if none found for this Owner.
912	     *
913	     * @param name to test
914	     * @return true if pet name is already in use
915	     */
916	    public Pet getPet(String name) {
917	        return getPet(name, false);
918	    }
919	
920	    /**
921	     * Return the Pet with the given name, or null if none found for this Owner.
922	     *
923	     * @param name to test
924	     * @return true if pet name is already in use
925	     */
926	    public Pet getPet(String name, boolean ignoreNew) {
927	        name = name.toLowerCase();
928	        for (Pet pet : getPetsInternal()) {
929	            if (!ignoreNew || !pet.isNew()) {
930	                String compName = pet.getName();
931	                compName = compName.toLowerCase();
932	                if (compName.equals(name)) {
933	                    return pet;
934	                }
935	            }
936	        }
937	        return null;
938	    }
939	
940	    public Pet getPet(Integer petId) {
941	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
942	    }
943	
944	    @Override
945	    public String toString() {
946	        return new ToStringCreator(this)
947	
948	            .append("id", this.getId())
949	            .append("new", this.isNew())
950	            .append("lastName", this.getLastName())
951	            .append("firstName", this.getFirstName())
952	            .append("address", this.address)
953	            .append("city", this.city)
954	            .append("telephone", this.telephone)
955	            .append("email", this.email)
956	            .toString();
957	    }
958	}
